    "detect_image_labels.py": "import os
import base64
import boto3
from botocore.exceptions import ClientError

AWS_REGION = os.getenv("AWS_REGION", "us-east-1")

def detect_image_labels(image_input: dict) -> list:
    rekognition_client = boto3.client("rekognition", region_name=AWS_REGION)
    image_data = {}

    if "image_bytes_base64" in image_input:
        image_bytes = base64.b64decode(image_input["image_bytes_base64"])
        image_data = {"Bytes": image_bytes}
    elif "image_s3_uri" in image_input:
        s3_uri = image_input["image_s3_uri"]
        bucket_name = s3_uri.split("//")[1].split("/")[0]
        object_name = "/".join(s3_uri.split("//")[1].split("/")[1:])
        image_data = {"S3Object": {"Bucket": bucket_name, "Name": object_name}}
    else:
        raise ValueError("Invalid image input. Must provide 'image_bytes_base64' or 'image_s3_uri'.")

    try:
        response = rekognition_client.detect_labels(
            Image=image_data,
            MaxLabels=10,
            MinConfidence=70
        )
        labels = []
        for label in response["Labels"]:
            labels.append({
                "name": label["Name"],
                "confidence": label["Confidence"]
            })
        return labels
    except ClientError as e:
        print(f"AWS Rekognition error: {e}")
        return []
