    "describe_image.py": "import os
import base64
from google.cloud import aiplatform
from google.cloud.aiplatform.generative_models import GenerationConfig, Part, GenerativeModel

PROJECT_ID = os.getenv("GOOGLE_CLOUD_PROJECT")
LOCATION = os.getenv("GOOGLE_CLOUD_LOCATION", "us-central1")


def describe_image(image_input: dict) -> str:
    if not PROJECT_ID:
        raise ValueError("GOOGLE_CLOUD_PROJECT environment variable not set.")

    aiplatform.init(project=PROJECT_ID, location=LOCATION)

    model = GenerativeModel("gemini-pro-vision")

    if "image_bytes_base64" not in image_input:
        raise ValueError("Invalid image input. Must provide 'image_bytes_base64'.")

    image_bytes = base64.b64decode(image_input["image_bytes_base64"])
    image_part = Part.from_data(data=image_bytes, mime_type="image/jpeg")

    generation_config = GenerationConfig(
        max_output_tokens=200,
        temperature=0.4,
        top_p=0.8,
        top_k=40
    )

    prompt_parts = [
        image_part,
        "Describe this image concisely in a few sentences, focusing on the main subjects and context."
    ]

    response = model.generate_content(
        prompt_parts,
        generation_config=generation_config
    )
    return response.text.strip()
