    "detect_image_text.py": "import os
import base64
from google.cloud import vision_v1
from google.cloud.vision_v1 import ImageAnnotatorClient

def detect_image_text(image_input: dict) -> list:
    client = ImageAnnotatorClient()

    if "image_bytes_base64" in image_input:
        image_bytes = base64.b64decode(image_input["image_bytes_base64"])
        image = vision_v1.Image(content=image_bytes)
    elif "image_gcs_uri" in image_input:
        image = vision_v1.Image(source=vision_v1.ImageSource(image_uri=image_input["image_gcs_uri"]))
    else:
        raise ValueError("Invalid image input. Must provide 'image_bytes_base64' or 'image_gcs_uri'.")

    response = client.text_detection(image=image)
    texts = []
    if response.text_annotations:
        # The first annotation is the overall text detected
        full_text = response.text_annotations[0].description
        texts.append({"full_text": full_text})

        # Subsequent annotations are individual words/lines
        for text in response.text_annotations[1:]:
            texts.append({
                "text": text.description,
                "bounds": [{
                    "x": vertex.x,
                    "y": vertex.y
                } for vertex in text.bounding_poly.vertices]
            })
    return texts
