    "image_summary.py": "import os
from openai import OpenAI
from vision_client import get_openai_client
from vision_models import AnalysisResults

OPENAI_MODEL = os.getenv("OPENAI_SUMMARIZATION_MODEL", "gpt-3.5-turbo")

def summarize_visual_analysis(analysis_results: dict) -> str:
    client = get_openai_client()

    labels_str = ", ".join([f"{l['name']} (confidence: {l['confidence']:.2f})" for l in analysis_results.get("labels", [])])
    text_str = "; ".join([t.get("full_text", t.get("text")) for t in analysis_results.get("detected_texts", []) if t.get("full_text") or t.get("text")])
    safety_str = ", ".join([f"{s['name']} (confidence: {s['confidence']:.2f})" for s in analysis_results.get("safety_labels", [])])

    prompt = f"""Given the following visual analysis results:
    - Detected Labels: {labels_str if labels_str else 'None'}
    - Image Description: {analysis_results.get('description', 'None')}
    - Detected Text: {text_str if text_str else 'None'}
    - Safety Labels: {safety_str if safety_str else 'None'}

    Provide a concise summary of the image's content and any notable findings.
    """

    try:
        response = client.chat.completions.create(
            model=OPENAI_MODEL,
            messages=[
                {"role": "system", "content": "You are a helpful assistant that summarizes visual analysis results."},
                {"role": "user", "content": prompt}
            ],
            max_tokens=250,
            temperature=0.5,
        )
        return response.choices[0].message.content.strip()
    except Exception as e:
        print(f"OpenAI summarization error: {e}")
        return "Failed to generate summary."
