    "alt_text_translate.py": "import os
from google.cloud import translate_v3
from vision_client import get_google_translate_client
from vision_models import TranslationResult

GOOGLE_CLOUD_PROJECT = os.getenv("GOOGLE_CLOUD_PROJECT")

def translate_alt_text(text: str, target_language_code: str, source_language_code: str = "en") -> dict:
    if not GOOGLE_CLOUD_PROJECT:
        raise ValueError("GOOGLE_CLOUD_PROJECT environment variable not set.")

    client = get_google_translate_client()
    parent = f"projects/{GOOGLE_CLOUD_PROJECT}/locations/global"

    try:
        response = client.translate_text(
            request={
                "parent": parent,
                "contents": [text],
                "mime_type": "text/plain",
                "source_language_code": source_language_code,
                "target_language_code": target_language_code,
            }
        )

        translation = response.translations[0]
        return {
            "translated_text": translation.translated_text,
            "detected_language_code": translation.detected_language_code
        }
    except Exception as e:
        print(f"Google Cloud Translation error: {e}")
        return {"translated_text": text, "detected_language_code": source_language_code}
