    "visual_safety_text.py": "import os
from openai import OpenAI
from vision_client import get_openai_client
from vision_models import ModerationResult

OPENAI_MODERATION_MODEL = os.getenv("OPENAI_MODERATION_MODEL", "text-moderation-latest")

def check_text_for_safety(texts: list[str]) -> list[dict]:
    client = get_openai_client()

    if not texts:
        return []

    try:
        response = client.moderations.create(input=texts, model=OPENAI_MODERATION_MODEL)

        results = []
        for item in response.results:
            results.append({
                "flagged": item.flagged,
                "categories": {k: v for k, v in item.categories},
                "category_scores": {k: v for k, v in item.category_scores}
            })
        return results
    except Exception as e:
        print(f"OpenAI Moderation error: {e}")
        return []
