    "image_asset_archive.py": "import os
import json
import boto3
from botocore.exceptions import ClientError
from vision_client import get_aws_s3_client

AWS_S3_BUCKET_NAME = os.getenv("AWS_S3_BUCKET_NAME")

def archive_image_analysis_artifacts(
    image_bytes: bytes,
    analysis_results: dict,
    output_filename_prefix: str
) -> dict:
    if not AWS_S3_BUCKET_NAME:
        raise ValueError("AWS_S3_BUCKET_NAME environment variable not set.")

    s3_client = get_aws_s3_client()

    image_key = f"{output_filename_prefix}/original_image.jpeg"
    results_key = f"{output_filename_prefix}/analysis_results.json"

    try:
        # Upload original image
        s3_client.put_object(
            Bucket=AWS_S3_BUCKET_NAME,
            Key=image_key,
            Body=image_bytes,
            ContentType="image/jpeg"
        )
        image_uri = f"s3://{AWS_S3_BUCKET_NAME}/{image_key}"

        # Upload analysis results as JSON
        results_json_bytes = json.dumps(analysis_results, indent=2).encode('utf-8')
        s3_client.put_object(
            Bucket=AWS_S3_BUCKET_NAME,
            Key=results_key,
            Body=results_json_bytes,
            ContentType="application/json"
        )
        results_uri = f"s3://{AWS_S3_BUCKET_NAME}/{results_key}"

        return {"image_s3_uri": image_uri, "analysis_results_s3_uri": results_uri}
    except ClientError as e:
        print(f"AWS S3 archiving error: {e}")
        return {}
